-- Biến động kho theo đơn (tính theo thứ tự thời gian; hủy đơn hoàn kho đúng một lần nhờ reference_code UNIQUE)
UPDATE inventory_movements SET created_at = UTC_TIMESTAMP() - INTERVAL 130 DAY WHERE reference_code LIKE 'SEED-%' AND reference_code NOT LIKE 'SEED-ORD-%' AND reference_code NOT LIKE 'SEED-REL-%' AND created_at > UTC_TIMESTAMP() - INTERVAL 130 DAY;
UPDATE product_variants v SET v.stock_quantity = (SELECT COALESCE(SUM(m.quantity_change), 0) FROM inventory_movements m WHERE m.variant_id = v.id) WHERE v.sku IN ('ML-011-01', 'ML-003-A', 'ML-005-01', 'MG-008-01', 'TL-012-A', 'TL-003-B', 'MG-009-A', 'ML-019-01', 'TL-001-01', 'TL-016-01', 'MG-007-01', 'MG-018-01', 'MG-013-A', 'TL-018-A', 'ML-017-01', 'ML-016-01', 'MG-016-01', 'ML-003-B', 'TL-007-01', 'TL-012-B', 'TL-002-01', 'TL-013-01', 'ML-010-01', 'MG-003-B', 'ML-018-01', 'TL-017-01', 'TL-003-A', 'MG-001-01', 'MG-006-A', 'MG-014-01', 'ML-014-01', 'ML-007-01', 'TL-004-01', 'TL-005-01', 'MG-011-01', 'MG-002-01', 'ML-006-B', 'ML-015-01', 'MG-005-01', 'TL-020-01', 'ML-009-B', 'ML-013-01', 'MG-004-01', 'TL-018-B', 'TL-009-B', 'MG-009-B', 'TL-010-01', 'TL-014-A', 'MG-013-B', 'MG-019-01', 'ML-004-01');

